// CV-CUDA, WarpCommon.cuh: the whole affine coordinate map
static __device__ __forceinline__ float2
calcCoord(const float *c_warpMat, int x, int y)
{
    const auto  fx   = static_cast<float>(x);
    const auto  fy   = static_cast<float>(y);
    const float xcoo = __fmaf_rn(fx, c_warpMat[0], fy * c_warpMat[1]) + c_warpMat[2];
    const float ycoo = __fmaf_rn(fx, c_warpMat[3], fy * c_warpMat[4]) + c_warpMat[5];
    return make_float2(xcoo, ycoo);
}

// Perspective adds one dot product and a reciprocal:
//   coeff = 1 / (fx*m6 + fy*m7 + m8);  xcoo = coeff * (fx*m0 + fy*m1 + m2);

// CV-CUDA, 14-bit fixed point (yuv_shift = 14)
#define CV_DESCALE(x, n) (((x) + (1 << ((n) - 1))) >> (n))

const int R2Y = 4899;   // 0.299 * 16384 = 4898.8
const int G2Y = 9617;   // 0.587 * 16384 = 9617.4
const int B2Y = 1868;   // 0.114 * 16384 = 1867.8

__device__ unsigned char luma(unsigned char R,
                              unsigned char G,
                              unsigned char B)
{
    int acc = R2Y * R + G2Y * G + B2Y * B;
    int Y   = CV_DESCALE(acc, 14);
    return (unsigned char)Y;
}

// CV-CUDA, FilterCommon.cuh: tile geometry for the 2-D tiled filter
const int tileW = outputW + kernelSize.x - 1;   // outputW = blockDim.x * Outputs
const int tileH = blockDim.y + kernelSize.y - 1;

inline size_t TiledSharedBytes(int outputs, dim3 block, int2 kernelSize, size_t elemSize)
{
    const size_t kernelBytes = kernelSize.x * kernelSize.y * sizeof(float);
    const size_t tileElems   = (block.x * outputs + kernelSize.x - 1)
                             * (block.y + kernelSize.y - 1);
    return RoundUpPowerOfTwo(tileElems * elemSize, sizeof(float)) + kernelBytes;
}

